<?php $title='Find Doctors | MediBook'; require 'partials/header.php'; $docs=db()->query('SELECT * FROM doctors ORDER BY specialty,name')->fetchAll(PDO::FETCH_ASSOC); ?>
<section class="page-title"><span class="eyebrow">Specialist network</span><h1>Find the right doctor</h1><p>Choose a specialist and continue to appointment booking.</p></section><section class="section"><div class="filter"><input id="doctorSearch" placeholder="Search by doctor or specialty" oninput="filterDoctors()"></div><div class="doctor-grid"><?php foreach($docs as $d):?><article class="doctor" data-search="<?=e(strtolower($d['name'].' '.$d['specialty']))?>"><div class="avatar"><?=e(substr($d['name'],4,1))?></div><div><h3><?=e($d['name'])?></h3><p class="accent"><?=e($d['specialty'])?></p><p><?=e($d['experience'])?> years experience • <?=e($d['availability'])?></p><strong>₹<?=e($d['fee'])?> consultation</strong></div><a class="btn small" href="book.php?doctor=<?=e($d['id'])?>">Book slot</a></article><?php endforeach;?></div></section><?php require 'partials/footer.php'; ?>